import numpy as np
from scipy import stats
from collections import defaultdict

MAX_DRIVERS = 4

def design(feats):
    # Check for correlation pairs with |r| >= 0.6
    corr_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if i != j:
                r, _ = stats.pearsonr(feats.x[:,i], feats.x[:,j])
                if abs(r) >= 0.6:
                    corr_pairs.add((fid1, fid2))

    # Remove near-duplicates (keep first occurrence)
    unique_ids = []
    seen = set()
    for fid in feats.ids:
        if fid not in seen:
            unique_ids.append(fid)
            seen.add(fid)

    # Calculate effect sizes and p-values for each feature
    effects = []
    for fid in unique_ids:
        idx = feats.column(fid)
        x = feats.x[:, idx]
        y = feats.y

        # Mean difference between groups
        mean_y1 = np.mean(x[y == 1])
        mean_y0 = np.mean(x[y == 0])
        effect_size = mean_y1 - mean_y0

        # Welch's t-test
        group0 = x[y == 0]
        group1 = x[y == 1]
        if len(group0) > 1 and len(group1) > 1:
            t_stat, p_val = stats.ttest_ind(group0, group1, equal_var=False)
        else:
            t_stat, p_val = 0, 1.0

        effects.append((fid, effect_size, t_stat, p_val))

    # Sort by absolute effect size
    effects.sort(key=lambda x: abs(x[1]), reverse=True)

    # Find significant features (p < 0.05) and their correlations
    sig_features = [f for f, _, _, p in effects if p < 0.05]
    sig_features_set = set(sig_features)

    # Identify potential drivers based on significance and lack of correlation with others
    drivers = []
    used_features = set()

    # First check if any feature shows strong effect and is not correlated with others
    for fid, effect, t_stat, p_val in effects:
        if p_val < 0.05 and fid not in used_features:
            # Check if this feature is not correlated with already selected drivers
            is_correlated = False
            for driver in drivers:
                if (fid, driver) in corr_pairs or (driver, fid) in corr_pairs:
                    is_correlated = True
                    break

            if not is_correlated:
                drivers.append(fid)
                used_features.add(fid)

                # Stop if we have enough drivers or reached max limit
                if len(drivers) >= MAX_DRIVERS:
                    break

    # If no clear driver found, return empty drivers
    if not drivers:
        return Design(
            drivers=(),
            columns=(),
            products=(),
            loadings={}
        )

    # Build regression features (include drivers and their interactions)
    columns = list(drivers)

    # Add interaction terms between drivers (if more than one)
    products = []
    for i, d1 in enumerate(drivers):
        for j, d2 in enumerate(drivers[i+1:], i+1):
            products.append((d1, d2))

    # For single driver, add weighted score using its standardized values
    if len(drivers) == 1:
        loadings = {drivers[0]: 1.0}
    else:
        # Use effect sizes as weights for multi-driver case
        loadings = {}
        for fid, effect, _, _ in effects:
            if fid in drivers:
                loadings[fid] = effect

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

